import{_ as t,o as e,c as l,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"安全协议分析","description":"","frontmatter":{},"headers":[],"relativePath":"安全方向/安全协议分析.md","filePath":"安全方向/安全协议分析.md","lastUpdated":1792430298000}'),i={name:"安全方向/安全协议分析.md"};function o(d,a,h,n,s,c){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="安全协议分析" tabindex="-1">安全协议分析 <a class="header-anchor" href="#安全协议分析" aria-label="Permalink to &quot;安全协议分析&quot;">​</a></h1><blockquote><p>校内第 4 学期核心课。协议是「安全机制的组合规则」，协议漏洞往往比算法漏洞更致命——算法没问题，用错了也能被攻破。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>TLS、SSH、IPSec、认证协议（Kerberos 等）是所有安全系统的骨架；</li><li>安全协议是 <a href="./密码学.html">密码学</a> 的实战延伸：把密码原语组合成可信的通信过程；</li><li>协议逻辑漏洞（重放、中间人、降级攻击）是研究级安全的重要领域。</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li><a href="./密码学.html">密码学</a>：加密、签名、密钥交换</li><li><a href="./../专业基础/计算机网络.html">计算机网络</a>：TCP、TLS 在分层中的位置</li><li>抓包工具：<a href="./../必学工具/抓包与流量分析.html">抓包与流量分析</a></li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>协议安全目标：机密性、完整性、认证、不可否认</li><li>常见协议族：TLS/HTTPS、IPSec、SSH、Kerberos、VPN</li><li>典型攻击：重放攻击、反射攻击、中间人、会话劫持、降级攻击</li><li>协议设计原则与形式化分析概念（Dolev-Yao 模型等）</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《网络安全协议：原理、结构与应用》（寇晓蕤等）</td><td>教材</td><td>中文协议分析经典教材</td></tr><tr><td>RFC 文档（TLS 1.3 等）</td><td>文档</td><td>权威一手资料（<a href="https://www.rfc-editor.org/" target="_blank" rel="noreferrer">rfc-editor.org</a>）</td></tr><tr><td>Wireshark 抓 TLS 流量分析</td><td>实操</td><td>观察握手过程（ClientHello→密钥交换→Application Data）</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>用 Wireshark 完整抓一次 HTTPS 握手，对照 RFC 把每个报文看懂——比读十遍书都有效；</li><li>思考题：为什么需要「随机数 + 时间戳」防重放？为什么证书体系可以防中间人？</li><li>与 <a href="./网络攻防.html">网络攻防</a> 配合：很多攻击（如 SSL 剥离、会话固定）本质是协议层面问题。</li></ul><h2 id="校内对应" tabindex="-1">校内对应 <a class="header-anchor" href="#校内对应" aria-label="Permalink to &quot;校内对应&quot;">​</a></h2><ul><li>安全协议分析（第 4 学期，核心课）</li></ul>',14)])])}const b=t(i,[["render",o]]);export{_ as __pageData,b as default};
